mapper.select:
SELECT r.reservation_id, r.visitor_name, r.phone, r.visit_date, r.headcount, r.status, r.created_at, r.cancel_reason, r.cancel_requested_at, p.name AS place_name, pay.amount, pay.payment_status FROM reservation r JOIN place p ON p.place_id = r.place_id LEFT JOIN payment pay ON pay.reservation_id = r.reservation_id WHERE r.place_id = #{placeId} AND p.member_id = #{bizMemberId}
AND r.status = #{status}
ORDER BY r.visit_date DESC, r.reservation_id DESC

SELECT COUNT(*) > 0
FROM reservation r
JOIN place p ON p.place_id = r.place_id
WHERE r.reservation_id = #{reservationId}
  AND p.member_id = #{bizMemberId}

mapper.update:
UPDATE place
SET is_closed = #{isClosed}
WHERE place_id = #{placeId}
  AND member_id = #{bizMemberId}

mapper.insert:
INSERT INTO place_closed_date (place_id, closed_date)
SELECT #{placeId}, #{closedDate}
FROM place p
WHERE p.place_id = #{placeId}
  AND p.member_id = #{bizMemberId}

mapper.delete:
DELETE d
FROM place_closed_date d
JOIN place p ON p.place_id = d.place_id
WHERE d.place_id = #{placeId}
  AND p.member_id = #{bizMemberId}
  AND d.closed_date BETWEEN #{startDate} AND #{endDate}

mapper.select:
SELECT member_role
FROM member
WHERE member_id = #{memberId}

SELECT COUNT(*) > 0
FROM place
WHERE place_id = #{placeId}

mapper.insert:
INSERT INTO place (
    place_id, place_type, min_price, region_id, member_id,
    name, description, extra_info, address,  first_image, hashtags
) VALUES (
    #{placeId}, #{placeType}, #{minPrice}, #{regionId}, #{memberId},
    #{name}, #{description}, #{extraInfo}, #{address},  #{firstImage}, #{hashtags}
)

mapper.delete:
DELETE FROM place_image
WHERE place_id = #{placeId}
  AND image_url = #{imageUrl}

mapper.select:
SELECT p.post_id, p.title, p.content, p.created_at, m.nickname AS nickname, p.readcount FROM post p JOIN member m ON m.member_id = p.member_id LEFT JOIN review_analysis ra ON ra.post_id = p.post_id WHERE p.place_id = #{placeId} AND p.category = '방문자인증후기'
AND ra.sentiment = #{sentiment}
ORDER BY p.post_id DESC
